    used_labels = set()

    def get_edge_labels():
        """Get all edge labels for currently assigned vertices"""
        labels = []
        for u, v in edges:
            if best[u] is not None and best[v] is not None:
                labels.append(abs(best[u] - best[v]))
        return labels

    def backtrack(v_idx):
        if v_idx == n_vertices:
            # Verify all edge labels are distinct
            edge_labels = get_edge_labels()
            if len(set(edge_labels)) == len(edge_labels) and len(edge_labels) == len(edges):
                return True
            return False

        for label in range(n_labels):
            if label in used_labels:
                continue

            # Make assignment
            best[v_idx] = label
            used_labels.add(label)

            # Check if any edge label is duplicated
            edge_labels = get_edge_labels()
            if len(set(edge_labels)) == len(edge_labels):
                if backtrack(v_idx + 1):
                    return True

            # Undo assignment
            best[v_idx] = None
            used_labels.remove(label)

        return False

    if backtrack(0):
        return best
    return None

